import numpy as np, base64, struct

SR = 44100

def b64_int16(arr):
    arr = np.asarray(arr, dtype=np.float64)
    arr = np.clip(arr, -1, 1)
    i16 = (arr * 32767).astype('<i2')
    return base64.b64encode(i16.tobytes()).decode('ascii')

def b64_float32(arr):
    arr = np.asarray(arr, dtype=np.float64)
    arr = np.clip(arr, -1, 1)
    f32 = arr.astype('<f4')
    return base64.b64encode(f32.tobytes()).decode('ascii')

def square(L, duty=0.5):
    x = np.arange(L)
    return np.where((x % L) < (duty*L), 1.0, -1.0)

def saw(L):
    x = np.arange(L)
    return ((x % L) / L) * 2 - 1

def triangle(L):
    x = np.arange(L)
    y = (x % L) / L
    return 4*np.abs(y-0.5)-1

def pulse(L, duty=0.25):
    x = np.arange(L)
    return np.where((x % L) < (duty*L), 1.0, -0.4)

def write_pcm(path, arr):
    import wave
    arr = np.clip(arr,-1,1)
    i16=(arr*32767).astype('<i2')
    with wave.open(path,'wb') as w:
        w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR)
        w.writeframes(i16.tobytes())

if __name__=="__main__":
    # test tonal sample: square wave, length 100
    sq = square(100)
    print("square100", b64_int16(sq))
